async function signOut(){herdaySignedImageCache.clear();herdayAccountLoadSerial++;await supabaseClient.auth.signOut();ACTIVE_AUTH_USER=null;ACTIVE_ACCOUNT=null;ADMIN_PENDING=[];S.route='home';save();render();scrollTo(0,0)}
