function beautyProfileStateCard(){let user=currentUser(),owns=!!user&&S.beautyOwnerId===user.id,state=owns?(S.verification||'none'):'none';if(!owns||!S.newName)return `<div class="profile-feature-card"><span class="profile-module-icon">♧</span><div><h3>Create Beauty Profile</h3><p>Offer your beauty services through a professional Beauty Profile on HerDay.</p><button class="profile-pill" onclick="nav('create')">Create Beauty Profile &nbsp;›</button></div></div>`;if(state==='pending')return `<div class="profile-feature-card"><span class="profile-module-icon">◷</span><div><h3>${esc(S.newName)}</h3><span class="status wait">Pending Review</span><p>Your Beauty Profile verification is awaiting HerDay review.</p><button class="profile-pill" onclick="nav('pending')">View Verification Status &nbsp;›</button></div></div>`;if(state==='needs_correction'||state==='needs-correction')return `<div class="profile-feature-card correction"><span class="profile-module-icon">ⓘ</span><div><h3>Needs Correction</h3><p>${esc(S.verificationCorrection?.reason||'HerDay requested a correction to your Beauty Profile.')}</p>${S.verificationCorrection?.note?`<div class="profile-admin-note">${esc(S.verificationCorrection.note)}</div>`:''}<button class="profile-pill" onclick="nav('create')">Review Beauty Profile &nbsp;›</button></div></div>`;if(state==='approved'&&S.beautyVerified===true)return `<div class="profile-feature-card approved"><span class="profile-module-icon">✓</span><div><div class="row between"><h3>${esc(S.newName)}</h3><span class="verified-professional">Verified ✓</span></div><p>Your professional Beauty Profile is approved and eligible to be public.</p><div class="profile-management"><button onclick="nav('my-beauty')">My Beauty Profile &nbsp;›</button><button onclick="nav('contacts')">Service Contacts &nbsp;›</button></div></div></div>`;return `<div class="profile-feature-card"><span class="profile-module-icon">♧</span><div><h3>Complete Beauty Profile</h3><p>Continue your professional Beauty Profile verification.</p><button class="profile-pill" onclick="nav('verify-info')">Continue Verification &nbsp;›</button></div></div>`}
