function adminProfilePage(){let user=currentUser();if(!user||user.role!=='admin')return '';let pending=pendingBeautyVerifications().length;return `${profileHeader('Admin Profile','admin')}${profileIdentity(user,true)}${profileMessagesShortcut()}<h2 class="account-section-title">Admin Tools</h2><div class="admin-modules">${ADMIN_MODULES.map(m=>`<button class="admin-module ${m[4]!=='future'?'functional':''}" onclick="${m[4]!=='future'?`nav('${m[4]}')`:`showPlaceholder('${m[1]}')`}"><span class="profile-module-icon">${m[0]}</span><div><h3>${m[1]}</h3>${m[2]?`<b>${m[2]}</b>`:''}<p>${m[3]}</p></div>${m[4]==='beauty-verifications'&&pending?`<em>${pending} Pending</em>`:''}<i>›</i></button>`).join('')}</div><h2 class="account-section-title">Account</h2><div class="account-list">${accountRow('♙','Edit Profile','showEditProfileDialog()')}${accountRow('▤','My Posts',`nav('my-posts')`)}${accountRow('♡','Saved Posts',`nav('saved-posts')`)}${accountRow('⚙','Account Settings',`nav('account-settings')`)}${accountRow('♧','Privacy & Safety',`nav('privacy-info')`)}${accountRow('?','Help & Support',`nav('help-info')`)}</div><button class="account-signout" onclick="signOut()"><span>↪</span>Sign Out<i>›</i></button>`}
function showPlaceholder(title){alert(`${title} will be implemented in its dedicated module.`)}
function showEditProfileDialog(){let user=currentUser();if(!user)return;REMOVE_ACCOUNT_PHOTO=false;adminDialog(`<h2>Edit Profile</h2><p>Update your HerDay personal profile details.</p><label class="dialog-label">First Name</label><input id="editFirst" class="field" value="${esc(user.firstName||'')}"><label class="dialog-label">Last Name</label><input id="editLast" class="field" value="${esc(user.lastName||'')}"><label class="dialog-label" for="editEmail">Email</label><input id="editEmail" class="field" type="email" value="${esc(user.email||'')}" readonly><label class="dialog-label">Cell Number <span>(Optional)</span></label><input id="editCell" class="field" value="${esc(user.cell||'')}"><label class="dialog-label" for="editAbout">About <span>(Optional · Public)</span></label><textarea id="editAbout" class="field" rows="4" maxlength="2000">${esc(user.about||'')}</textarea><label class="dialog-label" for="editCountry">Country <span>(Optional · Public)</span></label><input id="editCountry" class="field" autocomplete="country-name" maxlength="100" value="${esc(user.country||'')}"><label class="dialog-label" for="editCity">City <span>(Optional · Public)</span></label><input id="editCity" class="field" autocomplete="address-level2" maxlength="120" value="${esc(user.city||'')}"><label class="dialog-label upload-profile-photo">Profile Photo<input id="editPhoto" type="file" accept="image/jpeg,image/png,image/webp"></label>${user.avatarPath?'<button class="dialog-remove-photo" onclick="removeAccountPhoto()">Remove current photo</button>':''}<div class="admin-dialog-actions"><button class="btn secondary" onclick="closeAdminDialog()">Cancel</button><button class="btn primary" onclick="savePersonalProfile()">Save Changes</button></div>`)}
function removeAccountPhoto(){REMOVE_ACCOUNT_PHOTO=true;let b=$('.dialog-remove-photo');if(b){b.textContent='Photo will be removed';b.disabled=true}}
async function savePersonalProfile(){let user=currentUser();if(!user)return;let first=$('#editFirst').value.trim(),last=$('#editLast').value.trim(),cell=$('#editCell').value.trim(),about=$('#editAbout').value.trim(),country=$('#editCountry').value.trim(),city=$('#editCity').value.trim();if(!first||!last){alert('First and Last Name are required.');return}let oldPath=user.avatarPath||null,avatarPath=REMOVE_ACCOUNT_PHOTO?null:oldPath,file=$('#editPhoto').files?.[0];if(file){if(file.size>5*1024*1024||!['image/jpeg','image/png','image/webp'].includes(file.type)){alert('Use a JPEG, PNG or WebP photo no larger than 5 MB.');return}let ext={"image/jpeg":'jpg',"image/png":'png',"image/webp":'webp'}[file.type],path=`${user.id}/avatar-${Date.now()}.${ext}`,upload=await supabaseClient.storage.from('profile-photos').upload(path,file,{upsert:true});if(upload.error){alert(upload.error.message);return}avatarPath=path}let {error}=await supabaseClient.from('profiles').update({first_name:first,last_name:last,cell_number:cell||null,avatar_path:avatarPath,public_about:about||null,public_country:country||null,public_city:city||null}).eq('id',user.id);if(error){alert(error.message);return}if(oldPath&&oldPath!==avatarPath)await supabaseClient.storage.from('profile-photos').remove([oldPath]);REMOVE_ACCOUNT_PHOTO=false;await loadCurrentAccount();window.herdayAccountFeatures?.invalidateProfile();closeAdminDialog();render()}
function icon(c){const m={'Makeup':'💄','Bridal Services':'♕','Hair':'〰','Mehndi':'✋','Skin & Facial':'◉','Waxing':'✦','Threading & Brows':'⌁','Nails':'▯','Manicure & Pedicure':'✋','Lashes':'◡','Massage & Relaxation':'✿','Other Beauty Services':'✧'};return m[c]||'✦'}
const BEAUTY_CATEGORY_ICONS={
 'Makeup':'01_makeup.webp',
 'Bridal Services':'02_bridal_services.webp',
 'Hair':'03_hair.webp',
 'Mehndi':'04_mehndi.webp',
 'Skin & Facial':'05_skin_facial.webp',
 'Waxing':'06_waxing.webp',
 'Threading & Brows':'07_threading_brows.webp',
 'Nails':'08_nails.webp',
 'Manicure & Pedicure':'09_manicure_pedicure.webp',
 'Lashes':'10_lashes.webp',
 'Massage & Relaxation':'11_massage_relaxation.webp',
 'Other Beauty Services':'12_other_beauty_services.webp'
};
function categoryIcon(c){let file=BEAUTY_CATEGORY_ICONS[c];return file?`<img class="category-art" src="assets/beauty-categories/${file}" alt="" loading="lazy">`:icon(c)}
function beautyMainProviderCard(){let user=currentUser(),owns=!!user&&S.beautyOwnerId===user.id;if(!owns||!S.beautyProfileId)return `<div class="bcard provider-cta"><span class="round-icon">♙</span><div><b>Do you offer beauty services?</b><div class="muted">Create your professional Beauty Profile on HerDay.</div><button class="btn secondary" onclick="nav('create')">Create Beauty Profile &nbsp; ›</button></div></div>`;if(S.verification==='pending')return `<div class="bcard provider-cta"><span class="round-icon">◷</span><div><b>${esc(S.newName)}</b><div><span class="status wait">Pending Review</span></div><div class="muted">Your Beauty Profile verification is awaiting HerDay review.</div><button class="btn secondary" onclick="nav('pending')">View Verification Status &nbsp; ›</button></div></div>`;if(S.verification==='needs_correction'||S.verification==='needs-correction')return `<div class="bcard provider-cta"><span class="round-icon">ⓘ</span><div><b>${esc(S.newName||'Beauty Profile')}</b><div><span class="status wait">Needs Correction</span></div><div class="muted">Update the requested details in your existing Beauty Profile.</div><button class="btn secondary" onclick="nav('create')">Review Beauty Profile &nbsp; ›</button></div></div>`;if(S.verification==='approved')return `<div class="bcard provider-cta"><span class="round-icon">✓</span><div><b>${esc(S.newName)}</b><div class="muted">Your professional Beauty Profile is verified.</div><button class="btn secondary" onclick="nav('my-beauty')">My Beauty Profile &nbsp; ›</button></div></div>`;return `<div class="bcard provider-cta"><span class="round-icon">♙</span><div><b>${esc(S.newName||'Beauty Profile')}</b><div class="muted">Continue setting up your existing Beauty Profile.</div><button class="btn secondary" onclick="nav('create')">Continue Beauty Profile &nbsp; ›</button></div></div>`}
function locationCity(){let d=S.locationDetail||S.location||'';let parts=d.split(',').map(x=>x.trim()).filter(Boolean);let area=(S.location||'').trim().toLowerCase();let skip=new Set([area,'punjab','pakistan','pakistan.']);let city=parts.find(x=>!skip.has(x.toLowerCase())&&!/district|tehsil|division|province|postcode|postal/i.test(x));return city||S.location||'Choose a location'}
function main(){return head('Beauty Services','Beauty, closer to you.','home')+`<div class="bcard loc-card"><div class="loc-tabs"><button class="active" onclick="nearMe()"><svg class="inline-location-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="3"/></svg> Near Me</button><button onclick="chooseLocation()"><svg class="inline-location-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="3"/></svg> Choose Location ›</button></div><div class="location-now"><span class="round-icon"><svg class="inline-location-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="3"/></svg></span><div><b>${esc(locationCity())}</b>${locationCity()!==S.location?`<div class="muted">${esc(S.location)}</div>`:''}</div></div><div class="divider"></div><div class="muted">Find beauty professionals who serve this area.</div></div><label class="beauty-search-field"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/></svg><input aria-label="Search beauty services" class="searchbox" placeholder="What service are you looking for?" onkeydown="if(event.key==='Enter'){S.category=this.value||'Makeup';nav('results')}"></label><div class="row between"><h2 class="section-title">Explore Beauty</h2><button class="danger-link" onclick="nav('categories')">View all&nbsp; ›</button></div><div class="quick-grid">${B.quick.map(c=>`<button class="quick" onclick="nav('results',{category:'${c}'})"><span class="cat-icon">${categoryIcon(c)}</span><b>${c.replace('Skin & Facial','Skin / Facial')}</b></button>`).join('')}</div><div style="height:16px"></div><button class="btn primary" onclick="nav('results')">Find Providers &nbsp; ›</button>${beautyMainProviderCard()}`}
const APP_LOCATIONS=()=>[...new Set([...B.providers.flatMap(p=>p.areas),...(S.savedLocations||[]),...(S.newAreas||[])])];
let locationTimer=null,locationRequest=0;
function chooseLocation(){
 document.body.insertAdjacentHTML('beforeend',`<div id="locationPanel" class="location-panel" onclick="if(event.target===this)closeLocationSearch()"><div class="location-sheet"><div class="row between"><div><h2>Choose Location</h2><div class="muted">Search an area or address</div></div><button class="back" onclick="closeLocationSearch()">×</button></div><input id="locationQuery" class="field" autocomplete="off" placeholder="Search area, locality or address" oninput="locationInput(this.value)"><div id="locationResults" class="location-results"></div></div></div>`);
 renderLocationResults('',APP_LOCATIONS().map(x=>({name:x,detail:'Saved on HerDay'})));
 setTimeout(()=>$('#locationQuery')?.focus(),50);
}
function closeLocationSearch(){$('#locationPanel')?.remove()}
function normalizedSearchValue(v){return String(v||'').normalize('NFKC').trim().replace(/\s+/g,' ').toLocaleLowerCase()}
function locationInput(q){clearTimeout(locationTimer);locationRequest++;q=q.trim();let local=APP_LOCATIONS().filter(x=>normalizedSearchValue(x).includes(normalizedSearchValue(q))).map(x=>({name:x,matchingName:x,detail:'Saved on HerDay'}));renderLocationResults(q,local);if(q.length<3)return;locationTimer=setTimeout(()=>searchMapLocations(q,local),350)}
async function searchMapLocations(q,local=[]){const request=++locationRequest;let box=$('#locationResults');if(box)box.insertAdjacentHTML('beforeend','<div class="location-loading">Searching map locations…</div>');try{let u='https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&namedetails=1&limit=7&countrycodes=pk&q='+encodeURIComponent(q);let r=await fetch(u,{headers:{'Accept':'application/json'}});if(!r.ok)throw 0;let data=await r.json();let map=data.map(x=>{let name=x.name||x.address?.suburb||x.address?.neighbourhood||x.display_name.split(',')[0];return {name,matchingName:x.namedetails?.['name:en']||name,detail:x.display_name,lat:x.lat,lon:x.lon}});let seen=new Set(),all=[...local,...map].filter(x=>{let n=normalizedSearchValue(x.name),k=normalizedSearchValue(x.matchingName);if(seen.has(n)||seen.has(k))return false;seen.add(n);seen.add(k);return true}).slice(0,6);if(request===locationRequest)renderLocationResults(q,all)}catch(e){if(request===locationRequest)renderLocationResults(q,local,true)}}
function renderLocationResults(q,items,failed=false){const box=$('#locationResults');if(!box)return;box.replaceChildren();if(!items.length){const empty=document.createElement('div');empty.className='location-loading';empty.textContent=failed?'Map search unavailable. Try again.':q?'No matching location yet.':'Type to search map locations.';box.append(empty);return;}for(const item of items){const button=document.createElement('button');button.type='button';button.className='location-option';const name=document.createElement('b'),detail=document.createElement('small');name.textContent='⌖  '+item.name;detail.textContent=item.detail||'';button.append(name,detail);button.addEventListener('click',()=>selectLocation(JSON.stringify(item)));box.append(button);}}

function selectLocation(raw){let x=typeof raw==='string'?JSON.parse(raw):raw;S.location=x.name;S.locationMatch=x.matchingName||x.name;S.locationDetail=x.detail||x.name;S.locationCoords=x.lat&&x.lon?{lat:+x.lat,lon:+x.lon}:null;S.savedLocations=[...new Set([...(S.savedLocations||[]),x.name])];save();closeLocationSearch();render()}
function nearMe(){if(!navigator.geolocation){alert('Location is not available in this browser.');return}navigator.geolocation.getCurrentPosition(async pos=>{try{let u=`https://nominatim.openstreetmap.org/reverse?format=jsonv2&addressdetails=1&namedetails=1&lat=${pos.coords.latitude}&lon=${pos.coords.longitude}`;let r=await fetch(u,{headers:{'Accept':'application/json'}});if(!r.ok)throw 0;let x=await r.json(),a=x.address||{};if(a.country_code&&a.country_code.toLowerCase()!=='pk')throw new Error('Near Me is currently available for locations in Pakistan.');let name=a.suburb||a.neighbourhood||a.quarter||a.city_district||a.city||a.town||a.village||x.name;if(!name)throw 0;selectLocation(JSON.stringify({name,matchingName:x.namedetails?.['name:en']||name,detail:x.display_name||name,lat:pos.coords.latitude,lon:pos.coords.longitude}))}catch(e){alert(e.message||'Current area could not be identified. Please choose a location.')}},()=>alert('Allow location permission to use Near Me.'),{enableHighAccuracy:true,timeout:10000,maximumAge:60000})}
function categories(){return head('All Beauty Categories','What are you looking for?')+`<div class="cat-grid">${B.cats.map(c=>`<button class="cat" onclick="nav('results',{category:'${c}'})"><span class="cat-icon">${categoryIcon(c)}</span><b>${c}</b></button>`).join('')}</div>`}
function results(){let area=normalizedSearchValue(S.locationMatch||S.location),category=normalizedSearchValue(S.category);let ps=B.providers.filter(p=>area&&category&&p.areas.some(x=>normalizedSearchValue(x)===area)&&[...(p.cats||[]),...(p.services||[])].some(x=>normalizedSearchValue(x)===category));return head('Beauty Professionals',`${esc(S.category)} · ${esc(S.location)}`)+`<div class="bcard result-context"><div><span class="round-icon">${icon(S.category)}</span><span class="muted">Service</span><br><b>${esc(S.category)}</b><button class="btn secondary" onclick="nav('categories')">Change Service</button></div><div><span class="round-icon"><svg class="inline-location-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="3"/></svg></span><span class="muted">Location</span><br><b>${esc(S.location)}</b><button class="btn secondary" onclick="chooseLocation()">Change Location</button></div><div style="grid-column:1/-1;border-left:0;border-top:1px solid var(--line);margin-top:13px;padding-top:13px" class="muted">Showing professionals who serve this area.</div></div><div class="results-head"><h2 class="section-title">Matching Professionals</h2><span class="muted">${ps.length} results</span></div>${ps.length?ps.map(providerCard).join(''):`<div class="bcard empty-state"><span class="round-icon"><svg class="inline-location-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="3"/></svg></span><h3>No matching professionals yet</h3><p>We couldn’t find a beauty professional serving <b>${esc(S.location)}</b> for this search.</p><button class="btn secondary" onclick="chooseLocation()">Change Location</button></div>`}`}
function providerCard(p){return `<div class="bcard provider-card">${herdayBeautyAvatar(p)}<div><h3>${esc(p.name)} ${p.verified?'<span class="verified">✓</span>':''}</h3><div class="muted"><b>${p.cats.map(esc).join(' · ')}</b></div><div class="muted" style="margin-top:4px">${p.services.slice(0,3).map(esc).join(' · ')}</div><div class="muted" style="margin-top:6px">📍 Serves ${esc(p.areas[0])}${p.areas.length>1?' and nearby areas':''}</div><button class="btn secondary view-btn" onclick="nav('profile',{provider:'${p.id}'})">View Profile ›</button></div></div>`}
function profile(id){let p=B.providers.find(x=>x.id===id);if(!p)return head('Beauty Profile','','results')+'<div class="bcard empty-state"><h2>Profile unavailable</h2><p>This professional is not currently available.</p></div>';let rv=[];return head('Beauty Profile','', 'results')+`<div class="bcard profile-hero">${herdayBeautyAvatar(p)}<h2>${esc(p.name)} ${p.verified?'<span class="verified">✓</span>':''}</h2><div class="chips">${p.cats.map(c=>`<span class="chip">${icon(c)} &nbsp;${esc(c)}</span>`).join('')}</div><div class="metric-grid"><div class="metric"><span class="round-icon">⭐</span><div><b>${p.rating??'Not available'}</b><span class="muted">${p.count==null?'Ratings unavailable':p.count+' ratings'}</span></div></div><div class="metric"><span class="round-icon">✓</span><div><b>${p.completed??'Not available'}</b><span class="muted">Services Completed</span></div></div></div></div><div class="bcard content-card"><h2>About</h2><div class="muted">${esc(p.about)}</div></div><div class="bcard content-card"><h2>Services</h2><div class="service-list">${p.services.map((x,i)=>`<div class="service-row"><span class="service-icon">${i?icon(p.cats[Math.min(i,p.cats.length-1)]):'💄'}</span>${esc(x)}</div>`).join('')}</div></div><div class="bcard content-card"><h2>Service Areas</h2><div class="muted">Areas this professional serves</div>${p.areas.map(x=>`<div class="area-row"><span class="round-icon"><svg class="inline-location-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="3"/></svg></span>${esc(x)}</div>`).join('')}</div><button class="btn green" onclick="contact('${p.id}')">◉ &nbsp; Contact on WhatsApp &nbsp; ›</button><div class="bcard content-card"><h2>Ratings & Reviews</h2><div class="reviews-summary"><span class="round-icon">⭐</span><div><b>${p.rating??'Not available'}</b><div class="muted">${p.count==null?'Ratings unavailable':p.count+' ratings'}</div></div></div>${rv.length?rv.map(reviewCard).join(''):`<div class="empty">Reviews are not available yet.</div>`}</div>`}
function reviewCard(r){return `<div class="review"><div class="review-top"><div><b>${esc(r.name)}</b><div class="stars">${'★'.repeat(r.stars)}${'☆'.repeat(5-r.stars)}</div></div><span class="muted">${esc(r.date)}</span></div><div class="muted" style="color:var(--plum);margin-top:5px">${esc(r.text)}</div>${r.confirmed?'<span class="confirmed">● Confirmed Service</span>':''}<button class="report">Report Review</button></div>`}
function contact(pid){const p=B.providers.find(x=>x.id===pid);const phone=String(p?.phone||'').replace(/[^0-9]/g,'');if(!p||!/^\d{7,15}$/.test(phone)){alert('This professional’s WhatsApp contact is unavailable.');return;}window.open('https://wa.me/'+phone,'_blank','noopener,noreferrer');}
function createProfile(){let sel=S.newCats===undefined?[]:S.newCats,sv=S.newServices||[],ar=S.newAreas||[];if(typeof sv==='string')sv=sv.split(',').map(x=>x.trim()).filter(Boolean);if(typeof ar==='string')ar=ar.split(',').map(x=>x.trim()).filter(Boolean);S.newCats=sel;S.newServices=sv;S.newAreas=ar;let phone=(S.newPhone||'').replace(/^\+?92\s*/, '');return head('Create Beauty Profile','Create your professional presence on HerDay.')+`<div class="create-page"><div class="form-section photo-uploader"><h2>Professional Photo</h2><div class="avatar">${S.newPhoto?`<img src="${S.newPhoto}" alt="Selected professional photo">`:'♙'}</div><label class="upload-label" for="proPhoto">▣ &nbsp; Add Photo</label><input id="proPhoto" class="file-input" type="file" accept="image/*" onchange="selectProfilePhoto(this)"><div class="muted photo-help">This photo will appear on your public Beauty Profile.</div></div><div class="form-section"><h2>Professional / Parlor Name</h2><div class="icon-field"><span>♜</span><input id="proName" class="field" placeholder="e.g. Glam by Ayesha" value="${esc(S.newName||'')}"></div><div class="muted section-help">This is the professional name customers will see.</div></div><div class="form-section"><h2>About</h2><div class="icon-field textarea-icon"><span>▤</span><textarea id="proAbout" class="field" placeholder="Tell customers a little about your beauty services...">${esc(S.newAbout||'')}</textarea></div></div><div class="form-section"><h2>Beauty Categories</h2><div class="muted">Choose the categories you offer.</div><div class="drop"><button class="field category-select" onclick="$('#catDrop').classList.toggle('hidden')"><span>✦ &nbsp; Select categories</span><b>⌄</b></button><div id="catDrop" class="drop-menu hidden">${B.cats.map(c=>`<label><input type="checkbox" ${sel.includes(c)?'checked':''} onchange="toggleCat('${c}',this.checked)">${c}</label>`).join('')}<button class="btn primary small" onclick="$('#catDrop').classList.add('hidden');render()">Done</button></div></div><div class="chips">${sel.map(c=>`<button class="chip" onclick="toggleCat('${c}',false);render()">${c}<span>×</span></button>`).join('')}</div></div><div class="form-section"><h2>Your Services</h2><div class="muted">Add the services you personally offer.</div><div class="dynamic-add"><input id="serviceAdd" class="field" placeholder="✦  Service Name"><button class="btn primary small" onclick="addService()">Add Service</button></div><div class="dynamic-list">${sv.map((x,i)=>`<div class="dynamic-row"><span>⠿ &nbsp; ${esc(x)}</span><span><button aria-label="Edit service" onclick="editService(${i})">♢</button><button aria-label="Remove service" onclick="removeService(${i})">×</button></span></div>`).join('')}</div></div><div class="form-section"><h2>Service Areas</h2><div class="muted">Add the areas where you provide beauty services.</div><div class="dynamic-add"><div class="area-suggest"><input id="areaAdd" class="field" autocomplete="off" placeholder="⌖  Search area" oninput="areaSearch(this.value)"><div id="areaSuggestions" class="area-suggestions hidden"></div></div><button class="btn primary small" onclick="addArea()">Add Area</button></div><div class="muted area-help">Select the correct area name so customers can find you.</div><div class="dynamic-list">${ar.map((x,i)=>`<div class="dynamic-row"><span>📍 &nbsp; ${esc(x)}</span><button aria-label="Remove area" onclick="removeArea(${i})">×</button></div>`).join('')}</div></div><div class="form-section"><h2>WhatsApp Number</h2><div class="phone-field"><span class="wa-icon">◉</span><span class="phone-prefix">+92　⌄</span><input id="proPhone" class="field" inputmode="tel" placeholder="3XX XXXXXXX" value="${esc(phone)}"></div><div class="muted section-help">Customers will use this number to contact you after your profile is approved and live.</div></div><button class="btn primary continue-button" onclick="saveCreate()">Continue to Verification <span>›</span></button><div class="muted next-note">Next, you’ll verify your Beauty Profile with a WhatsApp voice note.</div></div>`}
function toggleCat(c,on){let a=new Set(S.newCats||[]);on?a.add(c):a.delete(c);S.newCats=[...a];save()}
function addService(){let v=$('#serviceAdd').value.trim();if(v){S.newServices=[...(S.newServices||[]),v];save();render()}}function removeService(i){S.newServices.splice(i,1);save();render()}
function editService(i){let current=S.newServices[i],v=prompt('Edit service name',current);if(v!==null&&v.trim()){S.newServices[i]=v.trim();save();render()}}
function selectProfilePhoto(input){let file=input.files&&input.files[0];if(!file)return;PENDING_BEAUTY_PHOTO_FILE=file;let reader=new FileReader();reader.onload=()=>{S.newPhoto=reader.result;render()};reader.readAsDataURL(file)}
let areaTimer=null;function areaSearch(q){clearTimeout(areaTimer);let box=$('#areaSuggestions');if(!box)return;q=q.trim();if(!q){box.classList.add('hidden');return}let local=APP_LOCATIONS().filter(x=>x.toLowerCase().includes(q.toLowerCase())).slice(0,5).map(x=>({name:x,detail:'Saved on HerDay'}));showAreaSuggestions(local);if(q.length>=3)areaTimer=setTimeout(async()=>{try{let r=await fetch('https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&limit=6&countrycodes=pk&q='+encodeURIComponent(q),{headers:{'Accept':'application/json'}});let d=await r.json();let map=d.map(x=>({name:x.name||x.display_name.split(',')[0],detail:x.display_name}));showAreaSuggestions([...local,...map])}catch(e){}},350)}
function showAreaSuggestions(items){let box=$('#areaSuggestions');if(!box)return;let seen=new Set();items=items.filter(x=>{let k=x.name.toLowerCase();if(seen.has(k))return false;seen.add(k);return true}).slice(0,8);box.innerHTML=items.map(x=>`<button type="button" onclick='pickArea(${JSON.stringify(JSON.stringify(x))})'><b>${esc(x.name)}</b><small class="muted">${esc(x.detail||'')}</small></button>`).join('');box.classList.toggle('hidden',!items.length)}
function pickArea(raw){let x=JSON.parse(raw);$('#areaAdd').value=x.name;$('#areaSuggestions')?.classList.add('hidden');S.pendingArea=x.name}
function addArea(){let v=(S.pendingArea||$('#areaAdd').value).trim();if(v&&!S.newAreas.includes(v)){S.newAreas=[...(S.newAreas||[]),v];S.savedLocations=[...new Set([...(S.savedLocations||[]),v])];S.pendingArea='';save();render()}}function removeArea(i){S.newAreas.splice(i,1);save();render()}
async function saveCreate(){let user=currentUser();if(!user)return nav('login');let existing=await resolveCurrentBeautyProfile(),editable=existing&&['draft','needs_correction','needs-correction','approved'].includes(existing.verification_status);if(existing&&!editable){await nav(existing.verification_status==='pending'?'pending':'user-profile');return}let name=$('#proName').value.trim(),about=$('#proAbout').value.trim(),phone=$('#proPhone').value.trim(),categories=S.newCats||[],services=S.newServices||[],areas=S.newAreas||[];if(!name||!phone||!categories.length||!services.length||!areas.length){alert('Please complete your professional name, WhatsApp number, categories, services and service areas.');return}let photoPath=S.newPhotoPath||null;if(PENDING_BEAUTY_PHOTO_FILE){let file=PENDING_BEAUTY_PHOTO_FILE,ext=(file.name.split('.').pop()||'jpg').toLowerCase(),path=`${user.id}/profile-${Date.now()}.${ext}`,upload=await supabaseClient.storage.from('beauty-profile-photos').upload(path,file,{upsert:true});if(upload.error){alert(upload.error.message);return}photoPath=path}let whatsapp='+92 '+phone.replace(/^\+?92\s*/,''),data,error;if(existing){let result=await supabaseClient.rpc(existing.verification_status==='approved'?'update_approved_beauty_profile':'update_own_beauty_profile',{target_profile_id:existing.id,new_professional_name:name,new_about:about||null,new_professional_photo_path:photoPath,new_whatsapp_number:whatsapp,new_categories:categories,new_services:services,new_service_areas:areas});data=Array.isArray(result.data)?result.data[0]:result.data;error=result.error}else{let result=await supabaseClient.from('beauty_profiles').insert({owner_id:user.id,professional_name:name,about:about||null,professional_photo_path:photoPath,categories,services,service_areas:areas,whatsapp_number:whatsapp}).select('*').single();data=result.data;error=result.error;if(error&&(error.code==='23505'||/unique|duplicate/i.test(error.message||''))){let found=await resolveCurrentBeautyProfile();if(found){await nav('create');return}}}if(error){alert(error.message);return}PENDING_BEAUTY_PHOTO_FILE=null;if(data)hydrateBeauty(data,await signedStorageUrl('beauty-profile-photos',data.professional_photo_path));else await resolveCurrentBeautyProfile();if(existing?.verification_status==='approved'){await resolveCurrentBeautyProfile();nav(S.verification==='pending'?'pending':'my-beauty')}else nav('verify-info')}
function verifyInfo(){let details=['Your Beauty Profile / Professional Name','The beauty services you provide','The areas where you provide your services'],opened=sessionStorage.getItem(VOICE_WHATSAPP_OPENED)==='1';return head('Verify Your Beauty Profile','A quick voice verification before your profile goes live.','create')+`<div class="verify-page voice-verify-page"><div class="bcard verify-hero voice-hero"><div class="big-illus voice-illus">◉<span>✓</span></div><div><h2>Voice Verification</h2><div class="muted">Send us a short voice note from the WhatsApp number you entered in your Beauty Profile.</div><span class="pill voice-only">♪ &nbsp; WhatsApp voice note</span></div></div><div class="bcard content-card voice-details-card"><h2>What to mention</h2><div class="muted intro-copy">Please include only these three details:</div>${details.map((x,i)=>`<div class="voice-detail"><span class="detail-number">${i+1}</span><span>${x}</span></div>`).join('')}</div><div class="bcard voice-reassurance"><span class="reassurance-icon">✓</span><div><b>No video, CNIC or documents required.</b><div class="muted">Your voice note is only used to confirm the details submitted in your Beauty Profile.</div></div></div><button class="btn primary send-voice-note" onclick="openVerificationWhatsApp()"><span class="whatsapp-mark">◉</span> Send Verification Voice Note</button><div class="muted voice-cta-help">WhatsApp will open so you can record and send the voice note yourself.</div><button class="btn secondary confirm-voice-note" onclick="confirmVoiceVerification()" ${opened?'':'disabled'}>I've Sent My Voice Note</button></div>`}
function openVerificationWhatsApp(){sessionStorage.setItem(VOICE_WHATSAPP_OPENED,'1');let confirmButton=$('.confirm-voice-note');if(confirmButton)confirmButton.disabled=false;window.location.href=`https://wa.me/${HERDAY_VERIFICATION_WHATSAPP}`}
async function confirmVoiceVerification(){if(sessionStorage.getItem(VOICE_WHATSAPP_OPENED)!=='1'||!S.beautyProfileId)return;let {data,error}=await supabaseClient.rpc('submit_beauty_profile_verification',{target_profile_id:S.beautyProfileId});if(error){alert(error.message);return}sessionStorage.removeItem(VOICE_WHATSAPP_OPENED);let row=Array.isArray(data)?data[0]:data;hydrateBeauty(row,await signedStorageUrl('beauty-profile-photos',row?.professional_photo_path));nav('pending')}

const ADMIN_CHECK_KEYS=['whatsapp','name','services','areas'];
function submittedBeautyProfile(){if(!String(S.newName||'').trim()||!S.beautyProfileId)return null;return {id:S.beautyProfileId,name:String(S.newName).trim(),about:String(S.newAbout||'').trim(),photo:S.newPhoto||'',cats:Array.isArray(S.newCats)?S.newCats:[],services:Array.isArray(S.newServices)?S.newServices:[],areas:Array.isArray(S.newAreas)?S.newAreas:[],phone:String(S.newPhone||'').trim(),submittedAt:S.verificationSubmittedAt||null,verification:S.verification||'draft'}}
function pendingBeautyVerifications(){if(isAdmin())return ADMIN_PENDING;let p=submittedBeautyProfile();return p&&p.verification==='pending'?[p]:[]}
function formatAdminDate(value){if(!value)return 'Not recorded';let d=new Date(value);return Number.isNaN(d.getTime())?'Not recorded':d.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'Asia/Karachi',calendar:'gregory'})}
function adminAvatar(p,extra=''){return `<div class="admin-avatar ${extra}">${p.photo?`<img src="${esc(p.photo)}" alt="${esc(p.name)} professional profile photo">`:'♙'}</div>`}
function beautyVerifications(){let profiles=pendingBeautyVerifications();return `${head('Beauty Verifications','Review pending Beauty Profile verifications.','admin-profile').replace('class="beauty-head"','class="beauty-head beauty-verifications-head"')}<button class="btn secondary" onclick="nav('beauty-approved-providers')">View Approved Providers</button><div class="admin-section-head"><h2>Pending Verifications</h2><span class="admin-count">${profiles.length}</span></div><div class="admin-pending-list">${profiles.length?profiles.map(adminPendingCard).join(''):`<div class="admin-empty"><span>ⓘ</span><div>No pending Beauty Profile verifications.</div></div>`}</div>`}
function beautyApprovedProviders(){return `${head('Approved Beauty Providers','Current approved professional profiles.','beauty-verifications')}<div class="admin-pending-list">${ADMIN_APPROVED.length?ADMIN_APPROVED.map(p=>`<article class="bcard admin-pending-card">${adminAvatar(p)}<div class="admin-pending-main"><div class="admin-card-title"><h3>${esc(p.name)}</h3><span class="status done">Verified ✓</span></div><div class="muted">${esc(p.cats.join(' · '))}</div><div class="muted">${esc(p.areas.join(' · '))}</div></div><div class="admin-card-foot"><button class="btn secondary admin-open-review" onclick="openApprovedBeautyProfile('${esc(p.id)}')">Open Profile &nbsp;›</button></div></article>`).join(''):`<div class="admin-empty"><span>ⓘ</span><div>No approved Beauty Profiles.</div></div>`}</div>`}
function openApprovedBeautyProfile(id){if(!isAdmin())return;let p=ADMIN_APPROVED.find(x=>x.id===id&&x.verification==='approved');if(!p)return;nav('beauty-approved-profile',{adminApprovedId:id})}
function beautyApprovedProfile(){if(!isAdmin())return '';let p=ADMIN_APPROVED.find(x=>x.id===S.adminApprovedId&&x.verification==='approved');if(!p)return head('Beauty Profile','','beauty-approved-providers')+`<div class="bcard admin-empty"><span>ⓘ</span><div>This approved profile is no longer available.</div></div>`;return head('Beauty Profile','','beauty-approved-providers')+`<div class="admin-review-status"><span class="status done">Approved${p.verified?' · Verified ✓':''}</span></div><div class="bcard admin-review-card admin-professional"><div class="admin-card-heading"><span>♙♙</span><h2>Professional Profile</h2></div><div class="admin-profile-body">${adminAvatar(p,'large')}<div><b class="admin-profile-name">${esc(p.name)}</b><div class="muted">Professional / Parlor Name</div><div class="admin-divider"></div><span class="muted approved-about-label">About</span><p>${esc(p.about||'No About information submitted.')}</p></div></div></div>${adminReadOnlySection('▦','Beauty Categories',p.cats,'categories')}${adminReadOnlySection('☷','Services',p.services,'services')}${adminReadOnlySection('⌖','Service Areas',p.areas,'areas')}<div class="bcard admin-review-card admin-whatsapp"><div class="admin-card-heading"><span>◉</span><h2>WhatsApp Number</h2></div><div class="admin-whatsapp-value"><span>◉</span><div><b>${esc(p.phone||'Not submitted')}</b><div class="muted">Submitted provider number</div></div></div></div>`}

function adminPendingCard(p){return `<article class="bcard admin-pending-card">${adminAvatar(p)}<div class="admin-pending-main"><div class="admin-card-title"><h3>${esc(p.name)}</h3><span class="status wait">◷ &nbsp; Pending Review</span></div><div class="admin-phone">◉ <span>${esc(p.phone||'No WhatsApp number submitted')}</span></div><div class="chips">${p.cats.map(c=>`<span class="chip">${esc(c)}</span>`).join('')}</div></div><div class="admin-card-foot pending-submission-foot"><div><span class="admin-calendar">▣</span><span class="muted submission-date-copy">Submitted on<br><b>${esc(formatAdminDate(p.submittedAt))}</b></span></div><button class="btn secondary admin-open-review" onclick="openBeautyReview('${p.id}')">Open Review &nbsp;›</button></div></article>`}
function openBeautyReview(id){let p=pendingBeautyVerifications().find(x=>x.id===id);if(!p)return;S.adminReviewId=id;S.adminVerificationChecks={};save();nav('beauty-verification-review')}
function beautyVerificationReview(){let p=pendingBeautyVerifications().find(x=>x.id===S.adminReviewId);if(!p||p.verification!=='pending')return head('Beauty Verification Review','', 'beauty-verifications')+`<div class="bcard admin-empty"><span>ⓘ</span><div>This pending verification is no longer available.</div></div>`;let checks=S.adminVerificationChecks||{};return head('Beauty Verification Review','', 'beauty-verifications')+`<div class="admin-review-status"><span class="status wait">◷ &nbsp; Pending Review</span></div><div class="bcard admin-review-card admin-professional"><div class="admin-card-heading"><span>♙♙</span><h2>Professional Profile</h2></div><div class="admin-profile-body">${adminAvatar(p,'large')}<div><b class="admin-profile-name">${esc(p.name)}</b><div class="muted">Professional / Parlor Name</div><div class="admin-divider"></div><span class="muted">About</span><p>${esc(p.about||'No About information submitted.')}</p></div></div></div>${adminReadOnlySection('▦','Beauty Categories',p.cats,'categories')}${adminReadOnlySection('☷','Services',p.services,'services')}${adminReadOnlySection('⌖','Service Areas',p.areas,'areas')}<div class="bcard admin-review-card admin-whatsapp"><div class="admin-card-heading"><span>◉</span><h2>WhatsApp Number</h2></div><div class="admin-whatsapp-value"><span>◉</span><div><b>${esc(p.phone||'Not submitted')}</b><div class="muted">Submitted provider number</div></div></div></div><div class="bcard admin-review-card admin-voice-check"><div class="admin-card-heading"><span>▤</span><h2>Voice Verification Check</h2></div><p class="muted">Check the voice note received on the HerDay verification WhatsApp and confirm that the submitted details match.</p><div class="admin-checks">${[['whatsapp','WhatsApp number matches'],['name','Professional / Parlor Name matches'],['services','Services match'],['areas','Service Areas match']].map(x=>`<label><input type="checkbox" ${checks[x[0]]?'checked':''} onchange="toggleAdminCheck('${x[0]}',this.checked)"><span>${x[1]}</span></label>`).join('')}</div><div class="admin-info-note"><span>ⓘ</span>Open WhatsApp separately to review the voice note.</div></div><div class="bcard admin-review-card admin-decision"><div class="admin-card-heading"><span>♢</span><h2>Review Decision</h2></div><p class="muted">Please complete the above checks before deciding on this Beauty Profile verification.</p><div class="admin-decision-actions"><button id="approveBeautyButton" class="btn primary" onclick="showApproveBeautyDialog()" ${adminChecksComplete()?'':'disabled'}>Approve &amp; Verify</button><button class="btn secondary" onclick="showCorrectionDialog()">Needs Correction</button></div></div>`}
function adminReadOnlySection(symbol,title,items,type){return `<div class="bcard admin-review-card"><div class="admin-card-heading"><span>${symbol}</span><h2>${title}</h2></div><div class="admin-readonly-list ${type}">${items.length?items.map(x=>`<div>${type==='areas'?'<span>⌖</span>':''}${esc(x)}</div>`).join(''):`<div class="muted">None submitted</div>`}</div></div>`}
function adminChecksComplete(){let checks=S.adminVerificationChecks||{};return ADMIN_CHECK_KEYS.every(k=>checks[k]===true)}
function toggleAdminCheck(key,checked){if(!ADMIN_CHECK_KEYS.includes(key))return;S.adminVerificationChecks={...(S.adminVerificationChecks||{}),[key]:!!checked};save();let button=$('#approveBeautyButton');if(button)button.disabled=!adminChecksComplete()}
function adminDialog(content){$('#adminDialog')?.remove();document.body.insertAdjacentHTML('beforeend',`<div id="adminDialog" class="admin-dialog-backdrop" onclick="if(event.target===this)closeAdminDialog()"><div class="admin-dialog">${content}</div></div>`)}
function closeAdminDialog(){$('#adminDialog')?.remove()}
function showApproveBeautyDialog(){if(!adminChecksComplete())return;adminDialog(`<h2>Approve this Beauty Profile?</h2><p>Confirm that you checked the verification voice note and the submitted Beauty Profile details match.</p><div class="admin-dialog-actions"><button class="btn secondary" onclick="closeAdminDialog()">Cancel</button><button class="btn primary" onclick="approveBeautyVerification()">Approve &amp; Verify</button></div>`)}
async function approveBeautyVerification(){if(!adminChecksComplete()||!S.adminReviewId)return;let {error}=await supabaseClient.rpc('approve_beauty_profile',{target_profile_id:S.adminReviewId,whatsapp_number_matches:true,professional_name_matches:true,services_match:true,service_areas_match:true});if(error){alert(error.message);return}S.adminVerificationChecks={};save();closeAdminDialog();await loadAdminPending();await loadApprovedBeauty();nav('beauty-verifications')}
function showCorrectionDialog(){let reasons=['WhatsApp number does not match','Professional name does not match','Services do not match','Service areas do not match','Voice note not received / cannot be reviewed','Other'];adminDialog(`<h2>Needs Correction</h2><p>Select the reason and add a short note if needed.</p><div class="admin-reasons">${reasons.map((x,i)=>`<label><input type="radio" name="correctionReason" value="${esc(x)}" ${i===0?'checked':''}><span>${esc(x)}</span></label>`).join('')}</div><textarea id="adminCorrectionNote" class="field" maxlength="300" placeholder="Admin note (optional)"></textarea><div class="admin-dialog-actions"><button class="btn secondary" onclick="closeAdminDialog()">Cancel</button><button class="btn primary" onclick="sendBeautyCorrection()">Send for Correction</button></div>`)}
async function sendBeautyCorrection(){let selected=document.querySelector('input[name="correctionReason"]:checked');if(!selected||!S.adminReviewId)return;let {error}=await supabaseClient.rpc('request_beauty_profile_correction',{target_profile_id:S.adminReviewId,selected_reason:selected.value,selected_note:$('#adminCorrectionNote')?.value.trim()||null});if(error){alert(error.message);return}S.adminVerificationChecks={};save();closeAdminDialog();await loadAdminPending();nav('beauty-verifications')}
function syncApprovedBeautyProvider(){for(let i=B.providers.length-1;i>=0;i--)if(B.providers[i].source==='supabase')B.providers.splice(i,1);for(const p of APPROVED_BEAUTY)B.providers.push({id:p.id,name:p.name,verified:true,cats:p.cats,services:p.services,areas:p.areas,about:p.about||'Beauty professional on HerDay.',rating:null,count:null,completed:null,photo:p.photo,phone:p.phone,source:'supabase'})}
let stream=null,rec=null,chunks=[],recTimer=null,recSeconds=0;
async function startCamera(){if($('#cameraScreen'))return;document.body.insertAdjacentHTML('beforeend',cameraHTML());const start=$('#startRec');start.disabled=true;$('#camMsg').textContent='Opening camera…';try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:true});const v=$('#camVideo');v.srcObject=stream;await new Promise(res=>{if(v.readyState>=2)return res();v.onloadedmetadata=()=>res()});await v.play();start.disabled=false;setCameraState('ready');$('#camMsg').textContent='Ready to record'}catch(e){$('#camMsg').textContent='Camera permission is required for live verification.'}}
function cameraHTML(){return `<div id="cameraScreen" class="camera-screen"><div class="camera-inner"><div class="camera-top"><button class="back" onclick="closeCamera()">×</button><b>Live Verification</b><span class="muted">Step 1 of 1</span></div><div class="camera-box"><video id="camVideo" autoplay muted playsinline></video><div class="camera-tip">Keep your face clearly visible</div><div class="face-guide"></div></div><div class="instruction"><div class="muted" style="color:#d1c5cf">Current instruction</div><b>Look directly at the camera</b><div class="muted" style="color:#d1c5cf">Keep your face inside the guide.</div></div><div id="readyBadge" class="ready-badge">● <span id="camMsg">Opening camera…</span></div><div class="camera-actions"><button id="stopRec" class="cam-action" disabled onclick="recordStop()"><span class="cam-circle">■</span>Stop Recording</button><button id="retake" class="cam-action state-hidden" onclick="retake()"><span class="cam-circle">↻</span>Retake</button><button id="startRec" class="cam-action" disabled onclick="recordStart()"><span class="cam-circle">●</span><span id="startLabel">Start Recording</span></button><button id="submitRec" class="cam-action primary" disabled onclick="submitVerification()"><span class="cam-circle">➤</span>Submit for Review</button></div><div class="progress">1 Record &nbsp; — &nbsp; 2 Stop &nbsp; — &nbsp; 3 Submit</div><div class="notice">▣ &nbsp; Your verification video is private.<br><span style="margin-left:24px">It will be permanently deleted after your verification is approved.</span></div><div class="camera-help">Need help?</div></div></div>`}
function setCameraState(state){let st=$('#startRec'),sp=$('#stopRec'),rt=$('#retake'),sb=$('#submitRec'),badge=$('#readyBadge');if(!st)return;st.classList.toggle('state-hidden',state!=='ready');sp.classList.toggle('state-hidden',state!=='recording');rt.classList.toggle('state-hidden',state!=='recorded');sb.classList.toggle('state-hidden',state==='recording');st.disabled=state!=='ready'||!(stream&&stream.active);sp.disabled=state!=='recording';rt.disabled=state!=='recorded';sb.disabled=state!=='recorded'||!chunks.length;badge?.classList.toggle('recording',state==='recording')}
function recordStart(){if(!stream||!stream.active||!window.MediaRecorder){$('#camMsg').textContent='Camera recorder is not ready';return}chunks=[];let opts={};for(const t of ['video/webm;codecs=vp8,opus','video/webm;codecs=vp8','video/webm']){if(MediaRecorder.isTypeSupported?.(t)){opts.mimeType=t;break}}try{rec=new MediaRecorder(stream,opts)}catch(e){try{rec=new MediaRecorder(stream)}catch(err){$('#camMsg').textContent='Recording is not supported in this browser';return}}rec.ondataavailable=e=>{if(e.data&&e.data.size>0)chunks.push(e.data)};rec.onerror=()=>{$('#camMsg').textContent='Recording error — please Retake';setCameraState('ready')};rec.onstop=()=>{clearInterval(recTimer);setTimeout(()=>{if(chunks.length){$('#camMsg').textContent='Video ready';setCameraState('recorded')}else{$('#camMsg').textContent='Recording failed — Retake';setCameraState('ready')}},120)};rec.start(200);recSeconds=0;setCameraState('recording');$('#camMsg').textContent='REC 00:00';recTimer=setInterval(()=>{recSeconds++;$('#camMsg').textContent=`REC ${String(Math.floor(recSeconds/60)).padStart(2,'0')}:${String(recSeconds%60).padStart(2,'0')}`},1000)}
function recordStop(){if(rec&&rec.state==='recording'){try{rec.requestData()}catch(e){};setTimeout(()=>{if(rec&&rec.state==='recording')rec.stop()},80)}}
function retake(){clearInterval(recTimer);chunks=[];rec=null;$('#camMsg').textContent='Ready to record';setCameraState('ready')}
function closeCamera(){clearInterval(recTimer);if(rec&&rec.state==='recording'){try{rec.stop()}catch(e){}}stream?.getTracks().forEach(t=>t.stop());stream=null;$('#cameraScreen')?.remove()}
function submitVerification(){if(!chunks.length)return;S.verification='pending';save();closeCamera();nav('pending')}
function pending(){setTimeout(()=>{$('.beauty-head')?.classList.add('pending-head');$('.beauty-shell')?.classList.add('pending-page')},0);return head('Verification Submitted','', 'beauty-main')+`<div class="bcard verify-hero"><div class="big-illus">♪✓</div><div><h2>Verification Submitted</h2><span class="status wait">◷ &nbsp; Pending Review</span><div class="muted" style="margin-top:10px">Your Beauty Profile verification has been submitted successfully. HerDay will review the details provided for your Beauty Profile.</div></div></div><div class="bcard content-card"><h2>What happens next?</h2><div class="steps">${[['▤','Details Submitted'],['✓','HerDay Review'],['♙','Profile Approved']].map(x=>`<div><span class="step-icon">${x[0]}</span><div class="muted">${x[1]}</div></div>`).join('')}</div><div class="muted" style="margin-top:14px">Your Beauty Profile remains pending while HerDay reviews the submitted details.<br><br>After approval, your Beauty Profile can go live with HerDay verification status.</div></div><div class="bcard row"><span class="round-icon">♙</span><div><b style="font:20px DMSerif,Georgia,serif">Beauty Profile</b><div><span class="status wait">◷ Awaiting Verification Approval</span></div><div class="muted">Your Beauty Profile will not appear in public provider searches until verification is approved.</div></div></div><div class="bcard row"><span class="round-icon">▣</span><div><b>Your submitted verification details are used to review your Beauty Profile.</b><div class="muted">HerDay compares the submitted details with the information in your Beauty Profile.</div></div></div><div class="bcard row"><span class="round-icon">ⓘ</span><div><b>No action is needed while your verification is under review.</b><div class="muted">You do not need to send anything else unless HerDay requests a correction.</div></div></div><button class="btn primary" onclick="nav('beauty-main')">Back to Beauty Services</button><div style="text-align:center;margin:15px;color:var(--pink)">Need help?</div>`}
function allContacts(){return []}
function contacts(){return head('Service Contacts','','beauty-main')+'<section class="bcard empty-state"><h2>Not available yet</h2><p>Verified service history and reviews are not available yet.</p></section>'}
function status(s){let m={contacted:['● Contacted',''],waiting:['● Waiting for Customer Confirmation','wait'],confirmed:['● Completed & Confirmed','done'],no:['● Not Confirmed','no']};let x=m[s]||[s,''];return `<span class="status ${x[1]}">${x[0]}</span>`}
