function localizedZodiacRange(index,lang){const spans=[[3,21,4,19],[4,20,5,20],[5,21,6,20],[6,21,7,22],[7,23,8,22],[8,23,9,22],[9,23,10,22],[10,23,11,21],[11,22,12,21],[12,22,1,19],[1,20,2,18],[2,19,3,20]],v=spans[index],locale={en:'en-US',ur:'ur-PK',hi:'hi-IN',bn:'bn-BD',ar:'ar'}[lang]||'en-US',f=new Intl.DateTimeFormat(locale,{month:'short',day:'numeric',timeZone:'UTC',calendar:'gregory'});return f.format(new Date(Date.UTC(2000,v[0]-1,v[1])))+' – '+f.format(new Date(Date.UTC(2000,v[2]-1,v[3])));}
function horoscopeDate(lang='en'){let locale={en:'en-US',ur:'ur-PK',hi:'hi-IN',bn:'bn-BD',ar:'ar'}[lang]||'en-US';return new Date().toLocaleDateString(locale,{month:'long',day:'numeric',year:'numeric',timeZone:'Asia/Karachi',calendar:'gregory'})}
function horoscopeHeader(back,title,subtitle=''){return herdayPageHeader({className:'horo-head',title,subtitle,extra:`<div class="horo-date">${horoscopeDate('en')}</div>`,button:`<button type="button" class="horo-back" aria-label="Back" onclick="herdayBack('${back}')"><svg class="internal-back-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 12H4m7-8-8 8 8 8"/></svg></button>`});}
function setHoroLanguage(){S.horoLang='en';save();render()}
function selectZodiac(name){S.horoSign=name;save();render()}
function openZodiac(name){S.horoSign=name||S.horoSign||'Libra';save();nav('horoscope-detail')}
function localizedSignName(index,lang){return (HORO_SIGN_NAMES[lang]||HORO_SIGN_NAMES.en)[index]||ZODIAC[index][0]}
function horoIcon(name){let paths={check:'<path d="m7 12 3 3 7-7"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8l1.1 1.1L12 21l7.7-7.5 1.1-1.1a5.5 5.5 0 0 0 0-7.8Z"/>',career:'<rect x="3" y="7" width="18" height="13" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12h18M10 12v2h4v-2"/>',health:'<path d="M20 4c-7 0-12 3-14 8-1 3 1 7 5 8 6 1 10-6 9-16Z"/><path d="M4 21c3-6 7-10 12-13"/>',guidance:'<path d="m12 2.8 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.4l6.2-.9L12 2.8Z"/>',share:'<circle cx="18" cy="5" r="2.5"/><circle cx="6" cy="12" r="2.5"/><circle cx="18" cy="19" r="2.5"/><path d="m8.2 10.8 7.5-4.4M8.2 13.2l7.5 4.4"/>',arrow:'<path d="M5 12h14M14 7l5 5-5 5"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${paths[name]||''}</svg>`}
