function horoscopeActive(){return {lang:'en',sign:ZODIAC.some(([n])=>n===S.horoSign)?S.horoSign:'Libra'};}
function retryDailyHoroscope(){const {lang,sign}=horoscopeActive();horoDaily.load(sign.toLowerCase(),lang,true);}
function horoscopeDetail(){
 const {lang,sign}=horoscopeActive(),index=ZODIAC.findIndex(x=>x[0]===sign),z=ZODIAC[index],u=HORO_UI[lang],status=HORO_STATUS[lang],rtl=['ur','ar'].includes(lang),row=horoDaily.peek(sign.toLowerCase(),lang);
 clearTimeout(horoRefreshTimer);
 horoRefreshTimer=setTimeout(()=>{if(S.route==='horoscope-detail')render();},row.status==='ready'?60000:30000);
 if(row.status==='loading')void horoDaily.load(sign.toLowerCase(),lang);
 const c=row.status==='ready'?row.content:null;
 const insights=c?['love','career','health','guidance'].filter(k=>c[k]!==null).map(k=>`<section class="insight-card"><div class="insight-title"><span class="insight-icon ${k}">${horoIcon(k==='love'?'heart':k)}</span><h2>${esc(u[k])}</h2></div><p class="horo-live-copy">${esc(c[k])}</p></section>`).join(''):'';
 const lucky=c?[
  c.lucky_color!==null?`<span class="lucky-item"><i class="lucky-visual lucky-symbol" aria-hidden="true">◇</i><small>${esc(u.color)}</small><b>${esc(c.lucky_color)}</b></span>`:'',
  c.lucky_number!==null?`<span class="lucky-item"><i class="lucky-visual number">${esc(c.lucky_number)}</i><small>${esc(u.number)}</small></span>`:'',
  c.mood!==null?`<span class="lucky-item"><i class="lucky-visual mood" aria-hidden="true">☺</i><small>${esc(u.mood)}</small><b>${esc(c.mood)}</b></span>`:''
 ].filter(Boolean):[];
 const content=c?`<h2 class="section-heading">${esc(u.reading)}</h2><section class="reading-card"><p class="horo-live-copy">${esc(c.reading)}</p></section>${insights?`<div class="insight-grid">${insights}</div>`:''}${lucky.length?`<h2 class="section-heading lucky-heading">${esc(u.details)}</h2><section class="lucky-card"><div style="grid-template-columns:repeat(${lucky.length},minmax(0,1fr))">${lucky.join('')}</div></section>`:''}<p class="horo-notice">${esc(status.notice)}</p><button class="share-horo" onclick="shareHoroscope()">${horoIcon('share')}<span>${esc(u.share)}</span></button>`:`<section class="reading-card horo-service-state" role="status" aria-live="polite"><p>${esc(status[row.status]||status.error)}</p>${row.status==='loading'?'':`<button class="view-horoscope" onclick="retryDailyHoroscope()">${esc(status.retry)}</button>`}</section>`;
 return `<div class="horoscope-page detail ${rtl?'rtl-copy':''}" lang="${lang}" dir="ltr">${horoscopeHeader('horoscope',u.title)}<section class="sign-identity" dir="${rtl?'rtl':'ltr'}"><span class="sign-symbol">${z[1]}︎</span><div class="sign-copy"><h2>${localizedSignName(index,lang)}</h2><p>${localizedZodiacRange(index,lang)}</p>${c?.traits?`<p class="sign-traits">${esc(c.traits)}</p>`:''}</div></section>${languageSelector(lang)}<main class="horo-dynamic horo-localized" dir="${rtl?'rtl':'ltr'}">${content}</main></div>`;
}
