async function shareHoroscope(){let lang='en',index=Math.max(0,ZODIAC.findIndex(x=>x[0]===(S.horoSign||'Libra'))),sign=localizedSignName(index,lang),txt=`HerDay — ${sign} Daily Horoscope`;if(navigator.share){try{await navigator.share({title:'HerDay Daily Horoscope',text:txt});return}catch(e){if(e?.name==='AbortError')return}}try{await navigator.clipboard.writeText(txt);alert('Horoscope copied for sharing.')}catch(e){alert(txt)}}
function myBeautyPage(){if(!S.beautyProfileId)return head('My Beauty Profile','','beauty-main')+`<div class="bcard"><p class="muted">Profile unavailable.</p></div>`;return head('My Beauty Profile','','beauty-main')+`<div class="bcard owner-beauty-card"><div class="row"><span class="round-icon">♙</span><div><h2>${esc(S.newName||'Beauty Profile')}</h2><span class="status done">Verified ✓</span><div class="muted">${esc((S.newCats||[]).join(' • '))}</div></div></div>${S.newAbout?`<p class="muted owner-about">${esc(S.newAbout)}</p>`:''}</div><button class="btn primary" onclick="nav('create')">Edit Beauty Profile</button><button class="btn secondary" onclick="nav('profile',{provider:S.beautyProfileId})">View Public Profile</button>`}
function accountSettingsPage(){let u=currentUser();return `<div class="account-settings-head">${head('Account Settings','',currentUser()?.role==='admin'?'admin-profile':'user-profile')}</div><div class="settings-list">${accountRow('▢','Change Password',`nav('change-password')`)}<div class="settings-static"><span>✉</span><div><b>Account Email</b><p>${esc(u?.email||'')}</p><small>Your account email cannot be changed here.</small></div></div><div class="settings-static"><span>♧</span><div><b>Notifications</b><p>Manage your HerDay notifications.</p></div><label class="switch"><input type="checkbox" ${u?.notificationsEnabled?'checked':''} onchange="updateNotificationsWeb(this.checked)"><i></i></label></div></div><h2 class="account-section-title">Danger Zone</h2><button class="danger-row" onclick="confirmDeleteAccount()"><span>♲</span><div><b>Delete Account</b><p>Permanently delete your HerDay account and data.</p></div><i>›</i></button>`}
function changePasswordPage(){return `${head('Change Password','','account-settings')}<div class="bcard content-card"><h2>Create a new password</h2><p class="muted">Use at least 8 characters.</p><label class="dialog-label">New Password</label><input id="newPassword" class="field" type="password" placeholder="Minimum 8 characters"><label class="dialog-label">Confirm New Password</label><input id="confirmNewPassword" class="field" type="password" placeholder="Confirm new password"></div><button class="btn primary" onclick="changePasswordWeb()">Update Password</button>`}
async function updateNotificationsWeb(enabled){let u=currentUser();if(!u)return;let {error}=await supabaseClient.from('profiles').update({notifications_enabled:enabled}).eq('id',u.id);if(error){alert('Could not update notifications.');render();return}ACTIVE_ACCOUNT={...u,notificationsEnabled:enabled};render()}
async function changePasswordWeb(){let p=$('#newPassword')?.value||'',c=$('#confirmNewPassword')?.value||'';if(p.length<8){alert('Password must be at least 8 characters.');return}if(p!==c){alert('Passwords do not match.');return}let {error}=await supabaseClient.auth.updateUser({password:p});if(error){alert('Could not update password.');return}herdayRecovery=false;alert('Password updated successfully.');nav('account-settings')}
async function confirmDeleteAccount(){if(!confirm('This permanently deletes your HerDay account and applicable owned data. This action cannot be undone.\n\nContinue only if you understand your account will be permanently deleted.'))return;let {error}=await supabaseClient.rpc('delete_own_account');if(error){alert('Account could not be deleted.');return}await supabaseClient.auth.signOut();ACTIVE_AUTH_USER=null;ACTIVE_ACCOUNT=null;S.route='login';save();render()}

