/* All saved/profile/inbox reading destinations preserve the original section ID. */
function herdayOpenContent(p,returnRoute=S.route){
 if(!HERDAY_UUID.test(p?.id||''))throw Error('Post unavailable.');
 const destinations={poetry:['poetry-post',{poetryPostKey:p.id,poetryReturn:returnRoute}],explore:['explore-post',{exploreId:p.id,exploreCategory:p.detail_key||'',exploreReturn:returnRoute}],girls_space:['gs-post',{gsPostId:p.id,gsTopic:p.detail_key||'discussions',gsReturn:returnRoute}],community:['community-question',{communityId:p.id,communityReturn:returnRoute}]};
 const target=destinations[p.section_key];if(!target)throw Error('Post unavailable.');return nav(...target);
}
window.addEventListener('online',()=>void herdayResumeSession());
window.addEventListener('focus',()=>void herdayResumeSession());
document.addEventListener('visibilitychange',()=>{if(!document.hidden)void herdayResumeSession();});
let herdayResumeBusy=false;
async function herdayResumeSession(){if(herdayResumeBusy||document.hidden)return;herdayResumeBusy=true;try{const {data}=await herdaySession();if(data?.session&&!currentUser())await bootstrapSupabase();}catch{console.warn('Session refresh deferred until connection returns.');}finally{herdayResumeBusy=false;}}

function herdayAccountReconnect(){setBeauty(true);app().className='beauty-shell auth-shell';app().innerHTML='<div class="auth-page"><h1>Reconnect to HerDay</h1><p class="auth-subtitle">Your account could not be loaded. Check your connection and retry.</p><button type="button" class="btn primary" onclick="bootstrapSupabase()">Retry</button><button type="button" class="btn secondary" onclick="nav(\'login\')">Log in again</button></div>';}
